const youtubeResults = $input.all();
const competitors = $('03 - Split Competitors').all();

const output = [];

for (let i = 0; i < youtubeResults.length; i++) {
  const youtubeItem = youtubeResults[i].json;
  const competitor = competitors[i]?.json;

  if (!competitor) {
    throw new Error(`Không tìm thấy competitor tương ứng ở index ${i}`);
  }

  const channel = youtubeItem.items?.[0];

  if (!channel) {
    throw new Error(
      `YouTube không trả về channel cho competitor: ${competitor.name}`
    );
  }

  const uploadsPlaylistId =
    channel.contentDetails?.relatedPlaylists?.uploads;

  if (!uploadsPlaylistId) {
    throw new Error(
      `Không tìm thấy uploads playlist của competitor: ${competitor.name}`
    );
  }

  output.push({
    json: {
      competitor_id: competitor.id,
      competitor_name: competitor.name,
      platform: competitor.platform,
      channel_id: competitor.channelId,
      uploads_playlist_id: uploadsPlaylistId
    }
  });
}

return output;

const playlistResponses = $input.all();
const competitors = $('05 - Extract Uploads Playlist').all();

const output = [];

for (let i = 0; i < playlistResponses.length; i++) {
  const playlist = playlistResponses[i].json;
  const competitor = competitors[i]?.json;

  if (!competitor) {
    throw new Error(
      `Không tìm thấy competitor tương ứng tại index ${i}`
    );
  }

  const videos = playlist.items ?? [];

  for (const video of videos) {
    const videoId = video.contentDetails?.videoId;

    if (!videoId) {
      continue;
    }

    output.push({
      json: {
        competitor_id: competitor.competitor_id,
        competitor_name: competitor.competitor_name,
        platform: competitor.platform,
        channel_id: competitor.channel_id,
        uploads_playlist_id: competitor.uploads_playlist_id,

        video_id: videoId,

        title: video.snippet?.title ?? "",
        description: video.snippet?.description ?? "",
        published_at:
          video.contentDetails?.videoPublishedAt ??
          video.snippet?.publishedAt ??
          null
      }
    });
  }
}

return output;

const items = $input.all();

const videoIds = items
  .map(item => item.json.video_id)
  .filter(Boolean);

if (videoIds.length === 0) {
  throw new Error('Không có video_id hợp lệ');
}

return [
  {
    json: {
      video_ids: videoIds.join(',')
    }
  }
];

const responses = $input.all();

if (responses.length === 0) {
  throw new Error('Không có dữ liệu từ Node 10 - Get Video Details');
}

// Node 10 chỉ tạo 1 item chứa items[]
const videos = responses[0].json.items ?? [];

if (videos.length === 0) {
  throw new Error('YouTube không trả về video nào');
}

// Lấy mapping competitor từ Node 05
const competitors = $('05 - Extract Uploads Playlist').all();

const competitorMap = new Map(
  competitors.map(item => [
    item.json.channel_id,
    {
      competitor_id: item.json.competitor_id,
      competitor_name: item.json.competitor_name,
      platform: item.json.platform
    }
  ])
);

const output = [];

for (const video of videos) {
  const snippet = video.snippet ?? {};
  const statistics = video.statistics ?? {};

  const contentId = video.id;
  const channelId = snippet.channelId;

  if (!contentId) {
    continue;
  }

  const competitor = competitorMap.get(channelId);

  if (!competitor) {
    throw new Error(
      `Không tìm thấy competitor cho channelId: ${channelId}`
    );
  }

  output.push({
    json: {
      competitor_id: competitor.competitor_id,
      competitor_name: competitor.competitor_name,
      platform: 'youtube',

      content_id: contentId,

      title: snippet.title ?? '',
      description: snippet.description ?? '',

      url: `https://www.youtube.com/watch?v=${contentId}`,

      published_at: snippet.publishedAt ?? null,

      views: Number(statistics.viewCount ?? 0),
      likes: Number(statistics.likeCount ?? 0),
      comments: Number(statistics.commentCount ?? 0),

      shares: null,

      captured_at: new Date().toISOString()
    }
  });
}

return output;

const wf02Results = $input.all();
const sourceItems = $('11 - Normalize Videos').all();

// Tạo map theo content_id để không phụ thuộc thứ tự item
const sourceMap = new Map();

for (const item of sourceItems) {
  const data = item.json;

  if (!data.content_id) {
    continue;
  }

  sourceMap.set(data.content_id, data);
}

const output = [];

for (const item of wf02Results) {
  const result = item.json;

  // Nếu WF02 xác định content không hợp lệ
  // thì không lưu metric
  if (result.processing_status === 'ignored_invalid') {
    continue;
  }

  // Với Duplicate branch:
  // content_id nằm trực tiếp ở result.content_id
  //
  // Với New branch:
  // POST backend có thể trả contentId bên trong result.data
  const contentId =
    result.content_id ??
    result.data?.contentId ??
    null;

  if (!contentId) {
    throw new Error(
      'Không tìm thấy content_id sau khi WF02 xử lý'
    );
  }

  const source = sourceMap.get(contentId);

  if (!source) {
    throw new Error(
      `Không tìm thấy dữ liệu metric gốc cho content_id: ${contentId}`
    );
  }

  output.push({
    json: {
      content_id: source.content_id,

      views: Number(source.views ?? 0),

      likes: Number(source.likes ?? 0),

      comments: Number(source.comments ?? 0),

      shares:
        source.shares === null ||
        source.shares === undefined
          ? null
          : Number(source.shares),

      captured_at: source.captured_at
    }
  });
}

return output;
